WITH filtered AS (SELECT *, CASE WHEN firmware IN ('1.1.0', '1.0.3') THEN 'Priority' ELSE 'Other' END AS firmware_group FROM device_readings WHERE HOUR(reading_ts) BETWEEN 11 AND 19), scored AS (SELECT id, device_code, reading_ts, temp_c, humidity, pressure, status_bits, ROW_NUMBER() OVER (PARTITION BY device_code ORDER BY humidity, id) AS row_seq, AVG(pressure) OVER (ORDER BY pressure, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS pressure_avg_5 FROM filtered), valid AS (SELECT *, status_bits * row_seq AS status_bits_times_row_seq FROM scored WHERE reading_ts > TO_DATE('2025-09-01')), with_gaps AS (SELECT *, CASE WHEN reading_ts - LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) > INTERVAL 15 MINUTES THEN 1 ELSE 0 END AS new_group_flag FROM valid), sessionized AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM with_gaps), filtered_device_readings AS (SELECT *, CAST(status_bits AS DOUBLE) AS status_bits_num, humidity / NULLIF(status_bits_times_row_seq, 0) AS humidity_per_status_bits_times_row_seq FROM sessionized WHERE reading_ts >= DATE '2025-09-01'), scored_device_readings AS (SELECT *, LAG(humidity) OVER w_grp AS prev_humidity, LEAD(humidity) OVER w_grp AS next_humidity, LEAD(temp_c) OVER w_grp AS next_temp_c, LAG(temp_c) OVER w_grp AS prev_temp_c, ROW_NUMBER() OVER w_grp AS event_seq, PERCENT_RANK() OVER (PARTITION BY device_code ORDER BY new_group_flag DESC NULLS LAST) AS new_group_flag_percent_rank FROM filtered_device_readings WHERE island_id <> 3 WINDOW w_grp AS (PARTITION BY device_code ORDER BY island_id, id)), latest AS (SELECT *, RANK() OVER (PARTITION BY device_code ORDER BY next_temp_c DESC NULLS LAST) AS rank_in_group FROM scored_device_readings QUALIFY rank_in_group = 1) SELECT id, reading_ts, temp_c, humidity, status_bits, status_bits_times_row_seq, new_group_flag, island_id, humidity_per_status_bits_times_row_seq FROM latest
